using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1. Strongly-typed retrieval — GetTypeInfo<T>() returns JsonTypeInfo<T> directly.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata   : {personInfo.Type.Name} (JsonTypeInfo<{personInfo.Type.Name}>)");

// Round-trip with the typed metadata to prove it works.
string json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Person p = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"Round-tripped        : {p}");

// 2. Probe without throwing — TryGetTypeInfo returns false when metadata isn't available
//    instead of throwing InvalidOperationException.
//    Switch to a resolver that only knows about Person, not about int.
options = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine(
        new SourceGenContext())        // only has Person
};

bool havePerson = options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? maybePerson);
bool haveInt    = options.TryGetTypeInfo(typeof(int),    out JsonTypeInfo? maybeInt);

Console.WriteLine($"Have Person metadata?: {havePerson} ({maybePerson?.Type.Name ?? "null"})");
Console.WriteLine($"Have int metadata?   : {haveInt} ({maybeInt?.Type.Name ?? "null"})");

// --- helper types --------------------------------------------------------

public record Person(string Name, int Age);

[JsonSerializable(typeof(Person))]
public partial class SourceGenContext : JsonSerializerContext;

